//! `ParticleSystem` against a capture of the pinned CesiumJS engine on a real
//! WebGL2 context with a seeded random number generator,
//! `tests/data/scene-particle-system.json` (generated by
//! `tools/cesium/generate-scene-particle-system.mjs`). After every frame the
//! system's timing and pool, every particle and the billboard it draws with,
//! every billboard and the billboard collection's vertex buffers are compared.

use cesium_rs::core::*;
use cesium_rs::renderer::{run_as_task, Context, Gl, GlValue, UniformFrame, UniformFrustum};
use cesium_rs::scene::billboard::BillboardImage;
use cesium_rs::scene::particle_system::*;
use cesium_rs::scene::{
    BoxEmitter, CircleEmitter, ConeEmitter, FrameResource, FrameState, ParticleBurst, ParticleBurstOptions,
    ParticleEmitter, ScenePrimitive, SphereEmitter,
};
use serde_json::Value;
use std::{cell::Cell, rc::Rc};

const ACTIVE_ATTRIBUTES: f64 = 35721.0;
const ACTIVE_UNIFORMS: f64 = 35718.0;

#[derive(Clone, Default)]
struct Host {
    next: Rc<Cell<u32>>,
}

impl Gl for Host {
    type Object = u32;
    fn drawing_buffer_size(&self) -> Result<[u32; 2], RuntimeError> {
        Ok([8, 8])
    }
    fn invoke(&self, name: &str, args: &[GlValue<u32>]) -> Result<GlValue<u32>, RuntimeError> {
        let number = |i: usize| match args.get(i) {
            Some(GlValue::Number(n)) => Some(*n),
            _ => None,
        };
        Ok(if name.starts_with("create") {
            self.next.set(self.next.get() + 1);
            GlValue::Object(self.next.get())
        } else {
            match name {
                "getParameter" => match number(0) {
                    Some(33901.) | Some(33902.) | Some(3386.) => GlValue::Numbers(vec![1., 4096.]),
                    _ => GlValue::Number(4096.),
                },
                "getExtension" => GlValue::Object(0),
                "getProgramParameter" if number(1) == Some(ACTIVE_ATTRIBUTES) => GlValue::Number(0.),
                "getProgramParameter" if number(1) == Some(ACTIVE_UNIFORMS) => GlValue::Number(0.),
                "getShaderParameter" | "getProgramParameter" => GlValue::Bool(true),
                "checkFramebufferStatus" => GlValue::Number(36053.),
                _ => GlValue::Null,
            }
        })
    }
}

fn fnv(bytes: &[u8]) -> String {
    let mut h: u64 = 0xcbf29ce484222325;
    for b in bytes {
        h = (h ^ *b as u64).wrapping_mul(0x100000001b3);
    }
    format!("{h:x}")
}

/// Every float32 NaN as 0x7fc00000, as the capture hashes vertex data.
fn canon(bytes: &[u8]) -> Vec<u8> {
    bytes
        .chunks(4)
        .flat_map(|c| {
            if f32::from_le_bytes([c[0], c[1], c[2], c[3]]).is_nan() {
                0x7fc00000u32.to_le_bytes().to_vec()
            } else {
                c.to_vec()
            }
        })
        .collect()
}

fn nums(v: &Value) -> Vec<f64> {
    v.as_array().unwrap().iter().map(|n| n.as_f64().unwrap()).collect()
}
fn c2(v: &Value) -> Cartesian2 {
    let n = nums(v);
    Cartesian2::new(n[0], n[1])
}
fn color(v: &Value) -> Color {
    let n = nums(v);
    Color::new(n[0], n[1], n[2], n[3])
}
fn matrix(v: &Value) -> Matrix4 {
    Matrix4(nums(v).try_into().unwrap())
}
fn emitter(v: &Value) -> Box<dyn ParticleEmitter> {
    let a = v.as_array().unwrap();
    let n = |i: usize| a[i].as_f64().unwrap();
    match a[0].as_str().unwrap() {
        "circle" => Box::new(CircleEmitter::new(Some(n(1)))),
        "sphere" => Box::new(SphereEmitter::new(Some(n(1)))),
        "cone" => Box::new(ConeEmitter::new(Some(n(1)))),
        _ => Box::new(BoxEmitter::new(Some(Cartesian3::new(n(1), n(2), n(3))))),
    }
}
fn image(v: &Value) -> ParticleImage<Host> {
    let p = nums(v);
    let (w, h, seed) = (p[0] as u32, p[1] as u32, p[2] as usize);
    Rc::new(move || {
        let bytes = (0..(w * h * 4) as usize).map(|k| ((k * 31 + seed * 17) & 255) as u8).collect();
        BillboardImage::pixels(w, h, bytes)
    })
}

fn options(o: &Value) -> ParticleSystemOptions<Host> {
    let mut s = ParticleSystemOptions::default();
    for (k, v) in o.as_object().unwrap() {
        let f = || v.as_f64().unwrap();
        match k.as_str() {
            "emitter" => s.emitter = Some(emitter(v)),
            "emissionRate" => s.emission_rate = Some(f()),
            "minimumParticleLife" => s.minimum_particle_life = Some(f()),
            "maximumParticleLife" => s.maximum_particle_life = Some(f()),
            "particleLife" => s.particle_life = Some(f()),
            "minimumSpeed" => s.minimum_speed = Some(f()),
            "maximumSpeed" => s.maximum_speed = Some(f()),
            "speed" => s.speed = Some(f()),
            "minimumMass" => s.minimum_mass = Some(f()),
            "maximumMass" => s.maximum_mass = Some(f()),
            "mass" => s.mass = Some(f()),
            "minimumImageSize" => s.minimum_image_size = Some(c2(v)),
            "maximumImageSize" => s.maximum_image_size = Some(c2(v)),
            "imageSize" => s.image_size = Some(c2(v)),
            "startColor" => s.start_color = Some(color(v)),
            "endColor" => s.end_color = Some(color(v)),
            "color" => s.color = Some(color(v)),
            "startScale" => s.start_scale = Some(f()),
            "endScale" => s.end_scale = Some(f()),
            "scale" => s.scale = Some(f()),
            "lifetime" => s.lifetime = Some(f()),
            "loop" => s.loop_animation = v.as_bool(),
            "sizeInMeters" => s.size_in_meters = v.as_bool(),
            "image" => s.image = Some(image(v)),
            "modelMatrix" => s.model_matrix = Some(matrix(v)),
            "emitterModelMatrix" => s.emitter_model_matrix = Some(matrix(v)),
            "bursts" => {
                s.bursts = Some(
                    v.as_array()
                        .unwrap()
                        .iter()
                        .map(|b| {
                            let b = nums(b);
                            ParticleBurst::new(ParticleBurstOptions {
                                time: Some(b[0]),
                                minimum: Some(b[1]),
                                maximum: Some(b[2]),
                            })
                        })
                        .collect(),
                )
            }
            "updateCallback" => {
                s.update_callback = Some(Box::new(|p, dt| {
                    p.velocity = p.velocity.multiply_by_scalar(1. - 0.5 * dt);
                    p.mass += dt;
                }))
            }
            other => panic!("unknown option {other}"),
        }
    }
    s
}

fn change(s: &mut ParticleSystem<Host>, k: &str, v: &Value) {
    match k {
        "emissionRate" => s.set_emission_rate(v.as_f64().unwrap()).unwrap(),
        "maximumParticleLife" => s.set_maximum_particle_life(v.as_f64().unwrap()).unwrap(),
        "emitterModelMatrix" => s.set_emitter_model_matrix(matrix(v)),
        "show" => s.show = v.as_bool().unwrap(),
        "startScale" => s.set_start_scale(v.as_f64().unwrap()).unwrap(),
        "endColor" => s.set_end_color(color(v)),
        "emitter" => s.set_emitter(emitter(v)),
        other => panic!("unknown change {other}"),
    }
}

fn frame(context: &Context<Host>) -> FrameState {
    let mut frustum = PerspectiveFrustum::new(std::f64::consts::PI / 3., 4. / 3.);
    (frustum.near, frustum.far) = (1., 1e9);
    let position = Cartesian3::new(2e7, 1e6, 5e6);
    let direction = position.negate().normalize();
    let right = direction.cross(Cartesian3::UNIT_Z).normalize();
    let up = right.cross(direction);
    let view = Matrix4::compute_view(position, direction, up, right);
    let uniform = cesium_rs::renderer::UniformCamera {
        view,
        inverse_view: view.inverse_transformation(),
        position,
        direction,
        right,
        up,
        cartographic: None,
        frustum: UniformFrustum::Perspective(frustum),
    };
    let culling = frustum.compute_culling_volume(position, direction, up);
    let mut frame =
        FrameState::new(UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)), culling, [8, 8]);
    frame.context = Some(FrameResource::new(context.clone()));
    frame.pixel_ratio = 1.;
    frame.minimum_disable_depth_test_distance = Some(0.);
    frame.passes.render = true;
    frame
}

fn close(actual: f64, expected: &Value, context: &str) {
    let expected = expected.as_f64().unwrap();
    assert!(
        actual == expected || (actual - expected).abs() <= 1e-9 * expected.abs().max(1.),
        "{context}: {actual} != {expected}"
    );
}
fn close_all(actual: &[f64], expected: &Value, context: &str) {
    let expected = expected.as_array().unwrap();
    assert_eq!(actual.len(), expected.len(), "{context}");
    for (k, (a, e)) in actual.iter().zip(expected).enumerate() {
        close(*a, e, &format!("{context}[{k}]"));
    }
}

#[test]
fn frames_match_cesium_particles_pool_billboards_and_buffers() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-particle-system.json")).unwrap();
    let mut frames_checked = 0;
    for (name, scenario) in fixture["scenarios"].as_object().unwrap() {
        math::set_random_number_seed(scenario["seed"].as_u64().unwrap() as u32);
        let context = Context::new_webgl2(Host::default());
        let mut system = ParticleSystem::new(options(&scenario["options"]));
        let completed_events = std::sync::Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let c = completed_events.clone();
        system.complete.add_event_listener(move |_| {
            c.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        });
        let start = JulianDate::from_iso8601("2024-01-01T00:00:00Z").unwrap();
        let mut frame = frame(&context);
        for (f, expected) in
            scenario["frames"].as_array().unwrap().iter().zip(fixture["capture"][name].as_array().unwrap())
        {
            let (seconds, frame_number) = (f[0].as_f64().unwrap(), f[1].as_u64().unwrap() as u32);
            let ctx = format!("{name} frame {seconds}");
            if let Some(changes) = f.get(2).and_then(Value::as_object) {
                for (k, v) in changes {
                    change(&mut system, k, v);
                }
            }
            frame.time = JulianDate::add_seconds(&start, seconds);
            frame.frame_number = frame_number;
            frame.command_list.clear();
            // One frame is one JavaScript task, as in Scene::render.
            run_as_task(|| {
                system.update(&mut frame).unwrap();
                for callback in std::mem::take(&mut frame.after_render) {
                    callback().unwrap();
                }
            });

            close(system.current_time(), &expected["currentTime"], &format!("{ctx} currentTime"));
            close(system.carry_over(), &expected["carryOver"], &format!("{ctx} carryOver"));
            assert_eq!(system.is_complete(), expected["complete"], "{ctx} complete");
            assert_eq!(
                completed_events.load(std::sync::atomic::Ordering::Relaxed) as u64,
                expected["completed"].as_u64().unwrap(),
                "{ctx} completed events"
            );
            assert_eq!(system.particle_estimate(), expected["particleEstimate"].as_f64().unwrap(), "{ctx} estimate");
            assert_eq!(frame.command_list.len() as u64, expected["commands"].as_u64().unwrap(), "{ctx} commands");

            let particles: Vec<_> = system.particles().zip(system.particle_billboards()).collect();
            let wanted = expected["particles"].as_array().unwrap();
            assert_eq!(particles.len(), wanted.len(), "{ctx} particle count");
            for (i, ((p, b), e)) in particles.iter().zip(wanted).enumerate() {
                let c = format!("{ctx} particle {i}");
                close_all(&[p.position.x, p.position.y, p.position.z], &e["position"], &format!("{c} position"));
                close_all(&[p.velocity.x, p.velocity.y, p.velocity.z], &e["velocity"], &format!("{c} velocity"));
                close(p.age(), &e["age"], &format!("{c} age"));
                close(p.normalized_age(), &e["normalizedAge"], &format!("{c} normalizedAge"));
                close(p.life, &e["life"], &format!("{c} life"));
                close(p.mass, &e["mass"], &format!("{c} mass"));
                close_all(&[p.image_size.x, p.image_size.y], &e["imageSize"], &format!("{c} imageSize"));
                assert_eq!(b.map(|b| b.index() as u64), e["billboard"].as_u64(), "{c} billboard");
            }
            let pool: Vec<Option<u64>> = system.pool_billboards().map(|b| b.map(|b| b.index() as u64)).collect();
            let wanted: Vec<Option<u64>> = expected["pool"].as_array().unwrap().iter().map(Value::as_u64).collect();
            assert_eq!(pool, wanted, "{ctx} pool");

            let collection = system.billboard_collection_mut().unwrap();
            let length = collection.length();
            let billboards: Vec<_> = (0..length).map(|i| collection.get(i).unwrap()).collect();
            let wanted = expected["billboards"].as_array().unwrap();
            assert_eq!(billboards.len(), wanted.len(), "{ctx} billboard count");
            for (i, (b, e)) in billboards.iter().zip(wanted).enumerate() {
                let c = format!("{ctx} billboard {i}");
                assert_eq!(b.show(), e["show"], "{c} show");
                let p = b.position();
                close_all(&[p.x, p.y, p.z], &e["position"], &format!("{c} position"));
                let k = b.color();
                // Exact: JSON round-trips doubles, and Cesium's lerp form matters to the last bit.
                assert_eq!(vec![k.red, k.green, k.blue, k.alpha], nums(&e["color"]), "{c} color");
                assert_eq!(b.scale(), e["scale"].as_f64().unwrap(), "{c} scale");
                assert_eq!(b.width(), e["width"].as_f64(), "{c} width");
                assert_eq!(b.height(), e["height"].as_f64(), "{c} height");
                assert_eq!(b.size_in_meters(), e["sizeInMeters"], "{c} sizeInMeters");
                assert_eq!(b.image().is_some(), e["hasImage"], "{c} hasImage");
                assert_eq!(b.ready(), e["ready"], "{c} ready");
            }

            let buffers: Vec<(u32, usize, String)> = collection.vertex_array_facade().map_or_else(Vec::new, |vaf| {
                vaf.buffer_layouts()
                    .into_iter()
                    .map(|(u, _, bytes)| (u as u32, bytes.len(), fnv(&canon(bytes))))
                    .collect()
            });
            let wanted: Vec<(u32, usize, String)> = expected["buffers"]
                .as_array()
                .unwrap()
                .iter()
                .map(|b| {
                    (
                        b["usage"].as_u64().unwrap() as u32,
                        b["length"].as_u64().unwrap() as usize,
                        b["hash"].as_str().unwrap().to_string(),
                    )
                })
                .collect();
            assert_eq!(buffers, wanted, "{ctx} vertex buffers");
            frames_checked += 1;
        }
        system.destroy().unwrap();
        assert!(system.update(&mut frame).is_err());
    }
    assert_eq!(frames_checked, 31);
}
